function generatePokemon(speciesId, level, isShiny = false) {
    const data = POKEDEX[speciesId];
    if (!data) return null;

    // Basic Stat calculation: (2 * Base * Level) / 100 + 5
    // HP is slightly different: (2 * Base * Level) / 100 + Level + 10
    const calcStat = (base) => Math.floor((2 * base * level) / 100) + 5;
    const calcHp = (base) => Math.floor((2 * base * level) / 100) + level + 10;

    const maxHp = calcHp(data.hp || data.baseHp);

    return {
        speciesId: speciesId,
        name: data.name,
        level: level,
        hp: maxHp,
        maxHp: maxHp,
        exp: 0,
        atk: calcStat(data.atk),
        def: calcStat(data.def),
        spatk: calcStat(data.spatk),
        spdef: calcStat(data.spdef),
        speed: calcStat(data.speed),
        moves: [...data.moves], // Clone array
        move: data.move, // Primary move reference
        isShiny: isShiny,
        frontSprite: isShiny ? (data.frontShiny || data.front) : data.front,
        backSprite: isShiny ? (data.backShiny || data.back) : data.back
    };
}



// Expose for Node.js backend to use the same logic
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        POKEDEX,
        MOVES,
        TYPES,
        getMultiplier,
        generatePokemon
    };
}
